SELECT 'core-2026-09-v4','past-habits','87b630c771d79eac83e3be02f06e226cf9455e201ca4d4e9ebd574542396373d',payload || '{"slug":"past-habits","title":"Past habits: used to, would and getting used to","level":"B1","order":35,"summary":"Distinguish a former habit from a familiar experience and from the process of adapting.","guidance":"Read the form and meaning together. Study the contrasts, then explain a worked example in your own words before starting a fresh practice session.","learningGoals":["Former habits and states","Repeated past actions with would","Being accustomed to something","The process of adapting"],"rules":[{"title":"Former habits and states","explanation":"Use **used to + base verb** for a past habit or state that contrasts with now. Used to can describe actions and states. In standard written questions and negatives after did, use **use to**.","pattern":"I **used to live** here. / Did you **use to live** here?","commonMistakes":["Used to is not a normal present-habit form. For habits now, use present simple."],"examples":["Complete a former habit: I used to **prepare** the visitor guide, but I do not do that now.","Complete a former habit: I used to **restore** the old portrait, but I do not do that now."],"skill":"form"},{"title":"Repeated past actions with would","explanation":"Would can recall repeated actions within an established past period. It normally needs a clear past setting and does not usually replace used to for a continuing state such as owning a house.","pattern":"When we were children, we **would visit** every summer.","commonMistakes":["We would own a cottage does not normally describe simple past ownership."],"examples":["Use did in the negative: I did not **use to prepare** the visitor guide in my old job.","Use did in the negative: I did not **use to restore** the old portrait in my old job."],"skill":"meaning"},{"title":"Being accustomed to something","explanation":"In **be used to**, used is an adjective and to is a preposition. Follow it with a noun or an -ing form. It means familiar or accustomed, and be can refer to present, past or future.","pattern":"She **is used to working** at night.","commonMistakes":["Is used to work does not mean that she is accustomed to working."],"examples":["I am familiar with the task: I am used to **preparing** the visitor guide.","I am familiar with the task: I am used to **restoring** the old portrait."],"skill":"contrast"},{"title":"The process of adapting","explanation":"**Get used to + noun / -ing** describes becoming accustomed. The tense belongs to get: am getting used to, got used to, will get used to. This is distinct from a discontinued habit.","pattern":"I’m **getting used to driving** on the left.","commonMistakes":["Do not add an extra be after get; get used to already expresses the change."],"examples":["Recall a repeated action with would: In my old job, I would **prepare** the visitor guide every week.","Recall a repeated action with would: In my old job, I would **restore** the old portrait every week."],"skill":"application"}],"tips":[],"source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-past-habits","bc-used-to"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"chapter":{"introduction":["Distinguish a former habit from a familiar experience and from the process of adapting.","The form tells you how to build the sentence; the context tells you why that form is useful. Read each section with both questions in mind. The examples make one contrast at a time, while the practice mixes the skills so that you learn to recognise the pattern yourself."],"rules":[{"title":"Former habits and states","explanation":"Use **used to + base verb** for a past habit or state that contrasts with now. Used to can describe actions and states. In standard written questions and negatives after did, use **use to**.","pattern":"I **used to live** here. / Did you **use to live** here?","commonMistakes":["Used to is not a normal present-habit form. For habits now, use present simple."],"examples":["Complete a former habit: I used to **prepare** the visitor guide, but I do not do that now.","Complete a former habit: I used to **restore** the old portrait, but I do not do that now."],"skill":"form","id":"past-habits-foundation-1","domain":"verbs","referenceIds":["bc-past-habits","bc-used-to"],"readingVersion":"core-2026-09-v3"},{"title":"Repeated past actions with would","explanation":"Would can recall repeated actions within an established past period. It normally needs a clear past setting and does not usually replace used to for a continuing state such as owning a house.","pattern":"When we were children, we **would visit** every summer.","commonMistakes":["We would own a cottage does not normally describe simple past ownership."],"examples":["Use did in the negative: I did not **use to prepare** the visitor guide in my old job.","Use did in the negative: I did not **use to restore** the old portrait in my old job."],"skill":"meaning","id":"past-habits-foundation-2","domain":"verbs","referenceIds":["bc-past-habits","bc-used-to"],"readingVersion":"core-2026-09-v3"},{"title":"Being accustomed to something","explanation":"In **be used to**, used is an adjective and to is a preposition. Follow it with a noun or an -ing form. It means familiar or accustomed, and be can refer to present, past or future.","pattern":"She **is used to working** at night.","commonMistakes":["Is used to work does not mean that she is accustomed to working."],"examples":["I am familiar with the task: I am used to **preparing** the visitor guide.","I am familiar with the task: I am used to **restoring** the old portrait."],"skill":"contrast","id":"past-habits-foundation-3","domain":"verbs","referenceIds":["bc-past-habits","bc-used-to"],"readingVersion":"core-2026-09-v3"},{"title":"The process of adapting","explanation":"**Get used to + noun / -ing** describes becoming accustomed. The tense belongs to get: am getting used to, got used to, will get used to. This is distinct from a discontinued habit.","pattern":"I’m **getting used to driving** on the left.","commonMistakes":["Do not add an extra be after get; get used to already expresses the change."],"examples":["Recall a repeated action with would: In my old job, I would **prepare** the visitor guide every week.","Recall a repeated action with would: In my old job, I would **restore** the old portrait every week."],"skill":"application","id":"past-habits-foundation-4","domain":"verbs","referenceIds":["bc-past-habits","bc-used-to"],"readingVersion":"core-2026-09-v3"},{"domain":"verbs","id":"habit-state-would-used","title":"Used to, would and past simple: meaning choices","explanation":"Used to can present a past state or habit that contrasts with the present. Habitual would normally needs an established past setting and describes repeated events. Past simple can express either without explicitly foregrounding the contrast with now. Choosing a form changes the presentation, even when all describe the same past period.","pattern":"We **used to live** nearby. / We **would walk** there daily.","examples":["As children, we **would build** shelters in the woods.","I **used to own** a motorbike."],"commonMistakes":["Would can describe a characteristic state in some special contexts, but ordinary past possession is better introduced with used to or past simple."],"referenceIds":["cambridge-comprehensive-scope"],"readingVersion":"core-2026-09-v4"}],"recap":["I **used to live** here. / Did you **use to live** here?","When we were children, we **would visit** every summer.","She **is used to working** at night.","I’m **getting used to driving** on the left."],"readingVersion":"core-2026-09-v4"},"stage":"3 · Time and experience","prerequisites":["future-perfect-continuous"],"readingReferenceIds":["bc-past-habits","bc-used-to","cambridge-comprehensive-scope"]}'::jsonb FROM grammar.content_catalog_topics W